sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var helpline = gs.getProperty('x_2223823_apollo_0.helpline_number', '1860 500 1066');
    template.print('<a style="color: #005f73; font-weight: bold; font-size: 15px; text-decoration: none;" href="tel:' + helpline.replace(/\s/g, '') + '">📞 ' + helpline + '</a>');
})(current, template, email, email_action, event);
